mapper.select:
WITH all_samples AS ( SELECT sample_unique_id FROM sample_derived WHERE sample_unique_id IN (
) ), mutated_samples AS ( SELECT sample_unique_id, hugo_gene_symbol, mutation_type FROM genomic_event_derived
AND variant_type = 'mutation'
AND hugo_gene_symbol = #{hugoGeneSymbol}
hugo_gene_symbol = #{filter.hugoGeneSymbol}
), profiled_samples AS ( SELECT DISTINCT sgp.sample_unique_id FROM sample_to_gene_panel_derived sgp INNER JOIN gene_panel_to_gene_derived gptg ON sgp.gene_panel_id = gptg.gene_panel_id WHERE sgp.sample_unique_id IN (
) AND gptg.gene = #{hugoGeneSymbol} AND sgp.alteration_type = 'MUTATION_EXTENDED' ) SELECT hugo_gene_symbol AS hugoGeneSymbol, 'mutations' AS profileType, REPLACE(mutation_type, '_', ' ') AS label, mutation_type AS value, CAST(COUNT(*) AS INT) AS count, CAST(COUNT(DISTINCT sample_unique_id) AS INT) AS uniqueCount,
GROUP_CONCAT(DISTINCT sample_unique_id) NULL AS sampleIdsStr FROM mutated_samples GROUP BY hugo_gene_symbol, mutation_type
UNION ALL SELECT #{hugoGeneSymbol} AS hugoGeneSymbol, 'Not Mutated' AS profileType, 'Not Mutated' AS label, 'NOT_MUTATED' AS value, CAST(COUNT(*) AS INT) AS count, CAST(COUNT(DISTINCT sample_unique_id) AS INT) AS uniqueCount, GROUP_CONCAT(DISTINCT sample_unique_id) AS sampleIdsStr FROM profiled_samples WHERE sample_unique_id NOT IN (SELECT sample_unique_id FROM mutated_samples) UNION ALL SELECT #{hugoGeneSymbol} AS hugoGeneSymbol, 'Not Profiled' AS profileType, 'Not Profiled' AS label, 'NOT_PROFILED' AS value, CAST(COUNT(*) AS INT) AS count, CAST(COUNT(DISTINCT sample_unique_id) AS INT) AS uniqueCount, GROUP_CONCAT(DISTINCT sample_unique_id) AS sampleIdsStr FROM all_samples WHERE sample_unique_id NOT IN (SELECT sample_unique_id FROM profiled_samples)
ORDER BY hugoGeneSymbol, profileType, value
